promql:
sum by (api) (
  increase(
    (
      api_calls_total{source_api="POST /api/v1/routeplanservice/routePlan/quickestRoute"}
      * ignoring(source_api) group_left
      (
        api_calls_total{source_api=~"POST /api/v1/travel2service/trips/left|POST /api/v1/travelservice/trips/left|POST /api/v1/basicservice/basic/travels|POST /api/v1/seatservice/seats/left_tickets"}
      )
    )[1h]
  )
)
